// Swift Example
import Foundation

enum ViewState<T> {
    case idle
    case loading
    case success(T)
    case error(Error)
}

@MainActor
class ProfileViewModel: ObservableObject {
    @Published var state: ViewState<User> = .idle

    func loadProfile() async {
        state = .loading
        do {
            // Network call implicitly off main thread if correctly configured
            let user = try await fetchUser()
            state = .success(user)
        } catch {
            state = .error(error)
        }
    }
}
